import sys
import shutil
import os

# Simple papermill stub that copies input notebook to output notebook
# Usage: papermill input.ipynb output.ipynb [flags...]
if len(sys.argv) >= 3:
    src = sys.argv[1]
    dst = sys.argv[2]
    try:
        if os.path.exists(src):
            shutil.copyfile(src, dst)
        else:
            open(dst, 'w').close()
    except Exception:
        sys.exit(1)
