"""Minimal networkx stub used for tests.

Provides gnm_random_graph(n, m, seed=None) returning a simple graph object with
.nodes and .neighbors(node) to satisfy tests.
"""
from __future__ import annotations

from random import Random
from typing import Iterable

class SimpleGraph:
    def __init__(self, n: int):
        self.nodes = list(range(n))
        self._adj = {i: set() for i in self.nodes}

    def add_edge(self, u: int, v: int) -> None:
        if u == v:
            return
        self._adj[u].add(v)
        self._adj[v].add(u)

    def neighbors(self, node: int) -> Iterable[int]:
        return self._adj.get(node, [])


def gnm_random_graph(n: int, m: int, seed: int | None = None) -> SimpleGraph:
    """Generate a simple undirected random graph with n nodes and m edges.

    This is a very small stub sufficient for the tests: nodes are 0..n-1 and
    edges are sampled uniformly without replacement among possible pairs.
    """
    rng = Random(seed)
    G = SimpleGraph(n)
    possible = [(i, j) for i in range(n) for j in range(i + 1, n)]
    rng.shuffle(possible)
    for u, v in possible[:m]:
        G.add_edge(u, v)
    return G

